function switchModel(modelName) {
  // تحديث النموذج النشط في بيئة العمل
  const availableModels = ["models/gemini-2.5-flash", "models/gemini-2.5-pro", "models/gemini-3.5-flash", "models/gemini-3.5-flash-lite"];
  if (availableModels.includes(modelName)) {
    this.activeModel = modelName;
    return `تم التحويل بنجاح إلى النموذج: ${modelName}`;
  } else {
    return "خطأ: النموذج غير مدعوم أو غير متاح.";
  }
}

